#pragma once

#include "mdaz/types.hpp"

namespace mdaz {

class IPlatform;

// Static Tilemap instances of the C2 "Map" layout (borders: water, sand, forest, base ground).
// Data: data/world_tilemaps.txt, generated by tools/extract_world_tilemaps.js.
class WorldTilemaps {
public:
  static const int kMaxMaps = 12;
  static const int kMaxTiles = 40000;

  WorldTilemaps();
  bool load(IPlatform& platform, const char* path);
  int count() const { return count_; }
  // Tile id at world position for maps using `image`, or -1.
  int tile_at(const char* image, float wx, float wy) const;
  // Draws every map whose image name starts with `prefix` around the camera.
  void draw(IPlatform& platform, const char* prefix, Vec2 cam, float scale,
            float view_w, float view_h) const;

private:
  struct Map {
    char image[40];
    float x, y;
    int cols, rows, tile_w, tile_h, atlas_cols;
    int first; // offset into tiles_
  };
  Map maps_[kMaxMaps];
  int count_;
  short tiles_[kMaxTiles];
  int tile_count_;
};

} // namespace mdaz
